const MEGA_NAMES=new Set([...Object.keys(MEGA_STONES),...Object.keys(CUSTOM_POKEMON_FORMS).filter(n=>n.startsWith('メガ'))]);
function isMegaPokemon(name){return MEGA_NAMES.has(normalizePokemonName(name))}
function megaStoneFor(name){const n=normalizePokemonName(name);return MEGA_STONES[n]||(MEGA_NAMES.has(n)?'メガストーン':'')}
function preMegaPokemonName(name){const n=normalizePokemonName(name);if(!isMegaPokemon(n))return n;return normalizePokemonName(n.replace(/^メガ/,'').replace(/[XY]$/,''))}
  function ensureSuggestionHost(input){let wrap=input.parentElement;if(!wrap.classList.contains('autocomplete-host')){const host=document.createElement('div');host.className='autocomplete-host';input.parentNode.insertBefore(host,input);host.appendChild(input);wrap=host}let box=wrap.querySelector(':scope > .autocomplete-list');if(!box){box=document.createElement('div');box.className='autocomplete-list';wrap.appendChild(box)}return box}
  function attachAutocomplete(input,type,onPick,context){
    if(!input||input.dataset.autocompleteBound)return;
    input.dataset.autocompleteBound='1';
    const box=ensureSuggestionHost(input);
    let suppress=false;
    const hide=()=>{box.classList.remove('show');box.innerHTML=''};
    const positionBox=()=>{const r=input.getBoundingClientRect(),gap=8,minLeft=Math.max(8,innerWidth*.5),left=Math.min(Math.max(minLeft,r.left+r.width*.48),innerWidth-180),width=Math.max(172,Math.min(420,innerWidth-left-gap)),top=Math.max(8,Math.min(innerHeight-110,r.bottom+4));box.style.setProperty('--ac-left',`${left}px`);box.style.setProperty('--ac-top',`${top}px`);box.style.setProperty('--ac-width',`${width}px`)};
    const render=()=>{
      if(suppress)return;
      const inferredPokemon=type==='move'?(context?.()||current()?.pokemon?.[Number(input.closest('[data-index]')?.dataset.index)]||''):'';
      const vals=type==='pokemon'?pokemonCandidates(input.value):type==='item'?itemCandidates(input.value):type==='savedMove'?savedMoveCandidates(input.value):moveCandidates(input.value,inferredPokemon);
      box.innerHTML=vals.map(v=>type==='pokemon'?`<button type="button" class="autocomplete-option autocomplete-pokemon-option"><img data-pokemon="${esc(v)}" src="${imgFor(v)}"><span>${esc(v)}</span></button>`:`<button type="button" class="autocomplete-option">${esc(v)}</button>`).join('');
      box.classList.toggle('show',vals.length>0);
      if(vals.length)positionBox();
      if(type==='pokemon')hydrateImages(box);
      box.querySelectorAll('button').forEach((b,i)=>{
        const pick=e=>{
          e.preventDefault();e.stopPropagation();
          suppress=true;
          input.value=vals[i];
          hide();
          input.dispatchEvent(new Event('input',{bubbles:true}));
          input.dispatchEvent(new Event('change',{bubbles:true}));
          if(onPick)onPick(vals[i]);
          input.blur();
          setTimeout(()=>{suppress=false},80);
        };
        b.addEventListener('pointerdown',pick,{once:true});
      });
    };
    input.addEventListener('input',render);
    input.addEventListener('focus',render);
    input.addEventListener('blur',()=>setTimeout(hide,80));
    input.addEventListener('keydown',e=>{if(e.key==='Escape'){hide();input.blur()}});
  }
