      let base=null,formData=null;
      if(!(meta.stats||[]).length){try{const formSlug=`${meta.base}-${String(meta.form||'mega').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;const r=await fetch(`https://pokeapi.co/api/v2/pokemon/${formSlug}`);if(r.ok)formData=await r.json()}catch(e){console.warn('custom mega form fetch failed',name,e)}}
      try{const r=await fetch(`https://pokeapi.co/api/v2/pokemon/${meta.base}`);if(r.ok)base=await r.json()}catch(e){console.warn('custom base fetch failed',name,e)}
      const statNames=['hp','attack','defense','special-attack','special-defense','speed'];
