  const DAMAGE_TYPES=['ノーマル','ほのお','みず','でんき','くさ','こおり','かくとう','どく','じめん','ひこう','エスパー','むし','いわ','ゴースト','ドラゴン','あく','はがね','フェアリー'];
  function teamLabel(t){return [t.title||'構築名未登録',t.user,t.rank,(t.pokemon||[]).filter(Boolean).join('・')].filter(Boolean).join(' / ')}
