  function captureBattleForm(root=activeDamageRoot()){const data={selfId:root.querySelector?.('#battleSelfTeam')?.value||'',opponentId:root.querySelector?.('#battleOpponentTeam')?.value||'',memo:root.querySelector?.('#battleMemo')?.value||'',result:root.querySelector?.('#battleResult')?.value||'W',calcName:root.querySelector?.('#damageCalcName')?.value||'',selections:JSON.parse(JSON.stringify(state.battleSelections||{self:[],opponent:[]})),panels:[]};root.querySelectorAll('[data-damage-atk],[data-damage-def]').forEach(panel=>data.panels.push({kind:panel.hasAttribute('data-damage-atk')?'atk':'def',index:Number(panel.dataset.damageAtk??panel.dataset.damageDef),values:readPanel(panel)}));return data}
