  function registerDamageSet(panel){if(!panel)return;const data=readPanel(panel),pokemon=normalizePokemonName(data.pokemon),name=panel.querySelector('[data-set-register-name]')?.value.trim(),memo=panel.querySelector('[data-set-register-memo]')?.value.trim();if(!pokemon){alert('先にポケモンを入力してください。');return}if(!name){alert('個体情報の名前を入力してください。');return}const a=blankAdjustment();a.pokemon=pokemon;a.setName=name;a.memo=memo||'';a.iv={H:31,A:31,B:31,C:31,D:31,S:31};a.ev={H:0,A:0,B:0,C:0,D:0,S:0};if(panel.hasAttribute('data-damage-atk')){const stat=data.category==='special'?'C':'A';a.ev[stat]=clampNum(data.offenseEv,0,32);a.nature=Number(data.nature)===1.1?(stat==='A'?'いじっぱり':'ひかえめ'):Number(data.nature)===.9?(stat==='A'?'ひかえめ':'いじっぱり'):''}else{a.ev.H=clampNum(data.hpEv,0,32);a.ev.B=clampNum(data.bEv,0,32);a.ev.D=clampNum(data.dEv,0,32);a.nature=data.defNature==='B'?'ずぶとい':data.defNature==='D'?'おだやか':''}const now=new Date().toISOString();state.individualSets.unshift({id:uid(),pokemon,name,adjustment:a,createdAt:now,updatedAt:now});scheduleSave();toast(`${pokemon}の「${name}」を個体として登録しました`)}
