  function openIndividualCreateMenu(){closeIndividualModal();state.individualCreatePokemon=document.getElementById("pokemonView")?.classList.contains("active")?state.currentPokemon:"";$("#pokemonSearchModal")?.classList.remove('show');const modal=document.createElement('div');modal.className='modal-backdrop show individual-create-modal';modal.innerHTML='<div class="sheet individual-choice-sheet"><button class="action-modal-close" data-individual-close>×</button><h3>個体を新規登録</h3><p class="sub">作り方を選んでください。My Teamには追加されません。</p><div class="individual-choice-grid"><button data-individual-new><b>＋ 初めから作る</b><span>ポケモンを選んですべて入力</span></button><button data-individual-copy><b>型を使う</b><span>登録済みの型をコピーして編集</span></button></div></div>';document.body.appendChild(modal);modal.onclick=e=>{if(e.target===modal||e.target.closest('[data-individual-close]'))closeIndividualModal()};modal.querySelector('[data-individual-new]').onclick=()=>state.individualCreatePokemon?openIndividualEditor(state.individualCreatePokemon):openIndividualPokemonStep;modal.querySelector('[data-individual-copy]').onclick=openIndividualSourceStep}
  function openIndividualPokemonStep(){closeIndividualModal();const modal=document.createElement('div');modal.className='modal-backdrop show individual-create-modal';modal.innerHTML='<div class="sheet individual-pokemon-step"><button class="action-modal-close" data-individual-close>×</button><h3>ポケモンを選択</h3><div class="individual-pokemon-preview"><img data-pokemon=""><b data-pokemon-label>名前を入力</b></div><div class="field"><label>ポケモン名</label><input data-individual-pokemon autocomplete="off" placeholder="例：メガプテラ"></div><button class="btn primary full" data-individual-next disabled>このポケモンで作る</button></div>';document.body.appendChild(modal);const input=modal.querySelector('[data-individual-pokemon]'),next=modal.querySelector('[data-individual-next]'),update=()=>{const n=normalizePokemonName(input.value);next.disabled=!n;modal.querySelector('[data-pokemon-label]').textContent=n||'名前を入力';const img=modal.querySelector('img');img.dataset.pokemon=n;img.src=imgFor(n);hydrateImages(modal)};attachAutocomplete(input,'pokemon',update);input.oninput=update;input.onchange=update;next.onclick=()=>openIndividualEditor(input.value);modal.onclick=e=>{if(e.target===modal||e.target.closest('[data-individual-close]'))closeIndividualModal()}}
  function openIndividualSourceStep(){closeIndividualModal();const rows=allIndividualSources(),modal=document.createElement('div');modal.className='modal-backdrop show individual-create-modal';modal.innerHTML=`<div class="sheet individual-source-sheet"><button class="action-modal-close" data-individual-close>×</button><h3>コピーする型を選択</h3><input class="search" data-source-search placeholder="構築名・型名で検索"><div class="individual-source-list">${rows.map((r,i)=>`<button data-source-index="${i}"><span class="individual-source-image"><img class="individual-source-pokemon" data-pokemon="${esc(r.pokemon)}" src="${imgFor(r.pokemon)}"><img class="individual-source-item" data-item="${esc(r.item||'')}" alt="${esc(r.item||'持ち物なし')}"></span><span class="individual-source-text"><b>${esc(r.label)}</b><small>${esc(r.sub)}</small></span><em>›</em></button>`).join('')||'<div class="empty">コピーできる型がありません。</div>'}</div></div>`;document.body.appendChild(modal);hydrateImages(modal);modal.querySelector('[data-source-search]').oninput=e=>{const q=searchNorm(e.target.value);modal.querySelectorAll('[data-source-index]').forEach((b,i)=>b.hidden=!!q&&!searchNorm(`${rows[i].pokemon} ${rows[i].label} ${rows[i].sub}`).includes(q))};modal.querySelectorAll('[data-source-index]').forEach((b,i)=>b.onclick=()=>openIndividualEditor(rows[i].pokemon,rows[i].adjustment));modal.onclick=e=>{if(e.target===modal||e.target.closest('[data-individual-close]'))closeIndividualModal()}}
  function openIndividualEditor(pokemon,source,editId=""){closeIndividualModal();const a=JSON.parse(JSON.stringify(source||blankAdjustment()));a.pokemon=normalizePokemonName(pokemon);if(isMegaPokemon(a.pokemon)&&!a.item)a.item=megaStoneFor(a.pokemon);a.iv={H:31,A:31,B:31,C:31,D:31,S:31,...(a.iv||{})};a.ev=sanitizeEffortObject(a.ev||{});a.moveSlots=Array.from({length:4},(_,i)=>(a.moveSlots||splitMoves(a.moves))[i]||'');const stats=['H','A','B','C','D','S'],modal=document.createElement('div');modal.className='modal-backdrop show individual-create-modal';modal.innerHTML=`<div class="sheet individual-editor-sheet"><div class="individual-editor-head"><button class="btn" data-individual-back>← 戻る</button><h3>${editId?"個体を編集":"個体を登録"}</h3><button class="action-modal-close" data-individual-close>×</button></div><div class="individual-editor-pokemon"><img data-pokemon="${esc(a.pokemon)}" src="${imgFor(a.pokemon)}"><div><b>${esc(a.pokemon)}</b><span>My Teamには追加されません</span></div></div><div class="individual-editor-grid"><div class="field wide"><label>型の名前</label><input data-set-name value="${esc(a.setName||'')}" placeholder="例：最速アタッカー型"></div><div class="field"><label>性格</label><select data-set-nature>${natureOptions(a.nature||'')}</select></div><div class="field"><label>特性</label><input data-set-ability value="${esc(a.ability||'')}"></div><div class="field"><label>持ち物</label><input data-set-item value="${esc(a.item||'')}"></div></div><div class="individual-move-editor"><h4>技構成</h4>${a.moveSlots.map((m,i)=>`<div class="field"><label>技${i+1}</label><input data-set-move="${i}" value="${esc(m)}" placeholder="技名"></div>`).join('')}</div><div class="individual-stat-editor"><h4>個体値・努力値</h4><div class="effort-remaining" data-set-remaining>残り ${effortRemaining(a.ev)} / 66</div><div class="stat-table stat-head"><span></span>${stats.map(k=>`<b>${k}</b>`).join('')}</div><div class="stat-table"><span>個体値</span>${stats.map(k=>`<input type="number" min="0" max="31" data-set-iv="${k}" value="${a.iv[k]}">`).join('')}</div><div class="stat-table"><span>努力値</span>${stats.map(k=>`<input type="number" min="0" max="32" data-set-ev="${k}" value="${a.ev[k]}">`).join('')}</div></div><div class="field"><label>調整意図・使用感</label><textarea data-set-memo>${esc(a.memo||'')}</textarea></div><button type="button" class="btn full individual-damage-button" data-set-temp-damage>この調整で一時的にダメージ計算</button><button class="btn primary full individual-save-button" data-set-save>${editId?"この内容で更新":"この内容で個体登録"}</button></div>`;document.body.appendChild(modal);hydrateImages(modal);modal.querySelector('[data-individual-back]').onclick=openIndividualCreateMenu;modal.onclick=e=>{if(e.target===modal||e.target.closest('[data-individual-close]'))closeIndividualModal()};attachAbilityAutocomplete(modal.querySelector('[data-set-ability]'),()=>a.pokemon);attachAutocomplete(modal.querySelector('[data-set-item]'),'item');modal.querySelectorAll('[data-set-move]').forEach(el=>attachAutocomplete(el,'move',null,()=>a.pokemon));modal.querySelectorAll('[data-set-ev]').forEach(el=>el.oninput=()=>{const fields=[...modal.querySelectorAll('[data-set-ev]')],total=fields.reduce((s,x)=>s+clampNum(x.value,0,32),0);if(total>66)el.value=Math.max(0,Number(el.value)-(total-66));modal.querySelector('[data-set-remaining]').textContent=`残り ${Math.max(0,66-fields.reduce((s,x)=>s+Number(x.value||0),0))} / 66`});modal.querySelector('[data-set-temp-damage]').onclick=()=>openIndividualTemporaryDamage(modal,a,editId);modal.querySelector('[data-set-save]').onclick=()=>{const name=modal.querySelector('[data-set-name]').value.trim();if(!name){alert('型の名前を入力してください。');return}a.setName=name;a.nature=modal.querySelector('[data-set-nature]').value;a.ability=modal.querySelector('[data-set-ability]').value.trim();a.item=modal.querySelector('[data-set-item]').value.trim();a.memo=modal.querySelector('[data-set-memo]').value.trim();a.iv=Object.fromEntries(stats.map(k=>[k,clampNum(modal.querySelector(`[data-set-iv="${k}"]`).value,0,31)]));a.ev=sanitizeEffortObject(Object.fromEntries(stats.map(k=>[k,clampNum(modal.querySelector(`[data-set-ev="${k}"]`).value,0,32)])));a.moveSlots=[...modal.querySelectorAll('[data-set-move]')].map(x=>x.value.trim());a.moves=a.moveSlots.filter(Boolean).join(' / ');const now=new Date().toISOString();saveIndividualEditorSet(editId,a,name,now);scheduleSave();closeIndividualModal();openPokemonPage(a.pokemon).then(()=>{state.pokemonSetTab='individual';state.pokemonPanelTab='individual';renderPokemonPage()});toast(`${a.pokemon}の「${name}」を${editId?"更新":"個体登録"}しました`)}}
  document.addEventListener('DOMContentLoaded',()=>{$('#pokemonBoxAdd').onclick=openIndividualCreateMenu;$('#scrollTopButton').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});const backInline=document.getElementById("pokemonBoxBackInline"),allInline=document.getElementById("pokemonBoxAll");if(backInline)backInline.onclick=closePokemonBoxModal;if(allInline)allInline.onclick=()=>{state.pokemonBoxType="all";renderPokemonQuickList()};const search=$('#pokemonIndexSearch');if(search&&!$('#pokemonBoxBackInline')){const row=document.createElement('div');row.className='pokemon-box-search-row';search.parentElement.before(row);const back=document.createElement('button');back.id='pokemonBoxBackInline';back.className='pokemon-box-back-inline';back.textContent='← 戻る';back.onclick=closePokemonBoxModal;const all=document.createElement("button");all.id="pokemonBoxAll";all.className="box-type-all-inline active";all.textContent="全";all.onclick=()=>{state.pokemonBoxType="all";renderPokemonQuickList()};row.append(back,search.parentElement,all)}})
  function normalizeAllPokemonNames(){state.teams.forEach(t=>{t.pokemon=(t.pokemon||[]).map(normalizePokemonName);(t.adjustments||[]).forEach((a,i)=>{a.pokemon=normalizePokemonName(a.pokemon||t.pokemon[i]||'')})});state.pairings.forEach(p=>{for(const k of ['pokemon','counterPokemon','complementPokemon','strongAgainstPokemon'])p[k]=(p[k]||[]).map(normalizePokemonName)});normalizePokemonRelations()}
  /* Ver.78: battle-result style basic selections */
